import{_ as a,o as i,c as l,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Object Storage Overview, Capabilities and Future Plans - Matt Benjamin, IBM","description":"","frontmatter":{"title":"Ceph Object Storage Overview, Capabilities and Future Plans - Matt Benjamin, IBM","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph","Object Storage","Distributed Storage","RGW","CephFS","BlueStore","BlueFS","RocksDB"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Object_Storage_Overview_Capabilities_and_Future_Plans_-_Matt_Benjamin_IBM.md","filePath":"posts/2023/Ceph_Object_Storage_Overview_Capabilities_and_Future_Plans_-_Matt_Benjamin_IBM.md","lastUpdated":1780459816000}'),r={name:"posts/2023/Ceph_Object_Storage_Overview_Capabilities_and_Future_Plans_-_Matt_Benjamin_IBM.md"};function o(n,e,s,_,u,h){return i(),l("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次会议由IBM的Program Director Matt Benjamin主持，主要讨论了Ceph对象存储的能力、路线图和未来计划。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Seth对象存储的能力</strong></p><ul><li><strong>RGW (RADOS Gateway)</strong> 作为Ceph集群之上的S3和Swift兼容的HTTP对象存储，具备高保真度。</li><li>主要能力包括： <ul><li>单集群容量可达数百PB。</li><li>支持数十万个S3桶或容器。</li><li>每个桶可存储至少5亿个对象，目标接近10亿。</li><li>动态桶索引缩放。</li></ul></li></ul></li><li><p><strong>近期开发和改进</strong></p><ul><li>重构和重写了多站点复制能力，提高规模和鲁棒性。</li><li>实现了S3 Select，支持结构化数据操作。</li><li>重构内部API为“Zipper”。</li><li>支持所有Amazon兼容的加密API。</li><li>将计算密集型操作从索引存储移至RADOS上的队列操作。</li></ul></li><li><p><strong>未来计划和路线图</strong></p><ul><li>更新C++20协程。</li><li>增强多站点复制功能，包括并行同步和同步公平性。</li><li>开发S3 Inventory，预生成的桶列表。</li><li>开发D4N缓存层。</li><li>扩展S3 Select功能，支持Parquet和JSON。</li><li>实现端到端跟踪，使用Jaeger。</li><li>实现索引恢复功能。</li></ul></li><li><p><strong>新前端协议</strong></p><ul><li>支持HTTP/3和Apache Arrow Flight。</li></ul></li><li><p><strong>其他增强功能</strong></p><ul><li>增强S3过渡能力，支持远程S3的数据恢复。</li><li>增强归档区域功能，包括数据去重。</li><li>消除单主节点模型，采用共识协议。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>确认了Seth对象存储的未来发展方向和技术路线图。</li><li>确定了即将实施的关键功能和技术改进。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>推进C++20协程的更新。</li><li>完成多站点复制功能的增强。</li><li>开发和测试新前端协议。</li><li>完善文档和社区支持。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li>讨论了文档更新、过滤器编译、动态脚本插入等技术细节。</li><li>确认了未来几年的发展目标和预期成果。</li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>会议强调了Seth对象存储在未来的发展方向和技术创新，旨在提供更高效、更灵活的存储解决方案，满足不断变化的市场需求和技术挑战。</p>',13)])])}const c=a(r,[["render",o]]);export{d as __pageData,c as default};
